from taf.ul.ettf.sim.core.command import Command
from taf.ul.ettf.sim.core.validator import Validator
from taf.ul.ettf.typed.custom_types import Margin, ThroughputValue
from taf.ul.ettf.typed.typed import typed


class BasicValidator(Validator):
    def __init__(self, selection_type=None, parameter=None):
        self._selection_type = selection_type
        self._parameter = parameter

    def validate(self, command_result):
        self.prepare_modulators()
        value = self.extract_value(command_result, self._parameter)
        return value

    def prepare_modulators(self):
        if not self._selection_type:
            self._selection_type = Command.command_elements.get_modulator('selection_type')
        if not self._parameter:
            self._parameter = Command.command_elements.get_modulator('parameter')

    def extract_value(self, command_result, parameter):
        return self._get_converted_value(command_result.get_value(self._selection_type, parameter))

    @typed(throughput_value=ThroughputValue())
    def _get_converted_value(self, throughput_value):
        return throughput_value


class AssertThatThroughput(BasicValidator):
    @typed(margin=Margin())
    def __init__(self, assertion_condition, selection_type, parameter=None, margin=.0):
        super(AssertThatThroughput, self).__init__(selection_type=selection_type, parameter=parameter)
        self._margin = margin
        self._assertion_condition = assertion_condition

    def validate(self, command_result):
        self.prepare_modulators()
        value = self.extract_value(command_result, self._parameter)
        self._assertion_condition(value, self._margin)


class AssertThatThroughputs(BasicValidator):
    @typed(margin=Margin())
    def __init__(self, assertion_condition, selection_type, parameters, margin=.0):
        super(AssertThatThroughputs, self).__init__(selection_type=selection_type)
        self._margin = margin
        self._assertion_condition = assertion_condition
        self._parameters = parameters

    def validate(self, command_result):
        self.prepare_modulators()
        values = [self.extract_value(command_result, parameter) for parameter in self._parameters]
        self._assertion_condition(values, self._margin)
